import glob

totals = {}
for path in glob.glob("orders/*.csv"):
    with open(path, encoding="utf-8") as f:
        next(f)
        for line in f:
            shop, cents = line.strip().split(",")
            totals[shop] = totals.get(shop, 0) + int(cents)
for shop in sorted(totals):
    print(f"{shop} {totals[shop] / 10:.2f}")
